SELECT stddev(p.value) AS standard_deviation FROM patients p JOIN procedures_icd pi ON p.subject_id = pi.subject_id WHERE p.gender = 1 AND p.anchor_year = 42 AND pi.icd_code IN (757071, 757072) AND p.subject_id IN (SELECT s.subject_id FROM admissions a JOIN patients s ON a.subject_id = s.subject_id WHERE a.admittime BETWEEN 2015 AND 2020 AND s.gender = 1 AND s.anchor_year BETWEEN 37 AND 47);